package com.andye.warmod.icbm.guidance;import java.util.UUID;import net.minecraft.core.BlockPos;import net.minecraft.world.phys.Vec3;public record IcbmGuidanceProfile(UUID siloId,BlockPos siloCentre,int guidanceTier,Vec3 requestedTarget,long guidanceSeed){public IcbmGuidanceProfile{guidanceTier=Math.max(0,Math.min(3,guidanceTier));if(siloId==null||siloCentre==null||requestedTarget==null||!requestedTarget.isFinite())throw new IllegalArgumentException("Invalid guidance profile");}}